staging/src/k8s.io/client-go/tools/remotecommand/errorstream.go L35-54 @ 42c4ddbe2d
OBSERVATION: This function watchErrorStream reads from errorStream and if there is a non-EOF error, it wraps it with fmt.Errorf using "%s" to convert the error to a string instead of wrapping it properly using "%w". This conversion prevents clients from using errors.Is or errors.As to inspect the original error, which matches the bug report description.
func watchErrorStream(errorStream io.Reader, d errorStreamDecoder) chan error {
	errorChan := make(chan error)

	go func() {
		defer runtime.HandleCrash()

		message, err := io.ReadAll(errorStream)
		switch {
		case err != nil && err != io.EOF:
			errorChan <- fmt.Errorf("error reading from error stream: %s", err)
		case len(message) > 0:
			errorChan <- d.decode(message)
		default:
			errorChan <- nil
		}
		close(errorChan)
	}()

	return errorChan
}

