pkg/controller/tainteviction/timed_workers.go L100-150 @ ef9e14db79
OBSERVATION: The TimedWorkerQueue's getWrappedWorkerFunc keeps the key in the workers map with value nil on success, to prevent duplicate work additions.
CancelWork deletes the key right after cancelling worker but a race condition can happen if CancelWork locks after the inner worker function locks.
This can leave the key with nil value in workers map permanently, causing subsequent AddWork calls to skip the work.
This explains the bug where work is skipped leading to pod stuck in Running state without eviction.
func (q *TimedWorkerQueue) getWrappedWorkerFunc(key string) func(ctx context.Context, fireAt time.Time, args *WorkArgs) error {
	return func(ctx context.Context, fireAt time.Time, args *WorkArgs) error {
		err := q.workFunc(ctx, fireAt, args)
		q.Lock()
		defer q.Unlock()
		if err == nil {
			// To avoid duplicated calls we keep the key in the queue, to prevent
			// subsequent additions.
			q.workers[key] = nil
		} else {
			delete(q.workers, key)
		}
		return err
	}
}

func (q *TimedWorkerQueue) CancelWork(logger klog.Logger, key string) bool {
	q.Lock()
	defer q.Unlock()
	worker, found := q.workers[key]
	result := false
	if found {
		logger.V(4).Info("Cancelling TimedWorkerQueue item", "item", key, "time", time.Now())
		if worker != nil {
			result = true
			worker.Cancel()
		}
