staging/src/k8s.io/apiserver/pkg/cel/library/cidr.go L221-234 @ 4205f04ce3
OBSERVATION: This function implements the containsCIDR logic used in the CEL validation rule. The bug likely originates here: the masking logic attempts to compare the masked prefix of the cidr with a new prefix created from containsCIDR's address but using cidr's prefix length, which seems reversed or incorrect. Also, the bit-length comparison is reversed: it should check that the "containsCIDR" prefix is larger (less or equal bits) than cidr's prefix for meaning containment. This incorrect masking and comparison causes the unexpected behavior when subnets are nested but have different base IP addresses.
func cidrContainsCIDR(arg ref.Val, other ref.Val) ref.Val {
	cidr, ok := arg.(apiservercel.CIDR)
	if !ok {
		return types.MaybeNoSuchOverloadErr(arg)
	}

	containsCIDR, ok := other.(apiservercel.CIDR)
	if !ok {
		return types.MaybeNoSuchOverloadErr(other)
	}

	equalMasked := cidr.Prefix.Masked() == netip.PrefixFrom(containsCIDR.Prefix.Addr(), cidr.Prefix.Bits())
	return types.Bool(equalMasked && cidr.Prefix.Bits() <= containsCIDR.Prefix.Bits())
}

