// getBackoffTime returns the time that podInfo completes backoff.
func (bq *backoffQueue) getBackoffTime(podInfo *framework.QueuedPodInfo) time.Time {
	maxBackoff := bq.podMaxBackoffDuration
	if maxBackoff == 0 {
