// InstallPathHandler installs a handler for a given path with multiple health checks.
func InstallPathHandler(mux mux.Router, path string, checks ...HealthChecker) {
	mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		for _, check := range checks {
			err := check.Check(r)
			if err != nil {
				w.WriteHeader(http.StatusServiceUnavailable)
				_, _ = w.Write([]byte("[+]" + check.Name() + " unhealthy: " + err.Error() + "\n"))
				return
			}
			_, _ = w.Write([]byte("[+]" + check.Name() + " ok\n"))
		}
		klog.V(4).Infof("healthz check passed, took %v", time.Since(start))
